def bucket_sort(arr: List[float]) -> List[float]:
    n = len(arr)
    if n == 0:
        return []
    buckets = [[] for _ in range(n)]
    for x in arr:
        bucket_index = int(n * x)
        if bucket_index == n:
            bucket_index = n - 1
        buckets[bucket_index].append(x)

    for i in range(n):
        if len(buckets[i]) > 1:
            buckets[i].sort()

    result = []
    for bucket in buckets:
        result.extend(bucket)
    return result

def bellman_ford(graph, source, num_vertices):
    # Initialize distances from source to all vertices as infinity
    distances = {node: float('inf') for node in range(num_vertices)}
    distances[source] = 0

    # Relax all edges (num_vertices - 1) times
    for _ in range(num_vertices - 1):
        updated = False
        for u, v, w in graph:
            if distances[u] != float('inf') and distances[u] + w < distances[v]:
                distances[v] = distances[u] + w
                updated = True
        if not updated:
            break  # Early termination if no updates

    # Check for negative weight cycles
    for u, v, w in graph:
        if distances[u] != float('inf') and distances[u] + w < distances[v]:
            return "Negative weight cycle detected"

    return distances

