def lengthOfLongestSubstring(s: str) -> int:
    if not s:
        return 0
    left = 0
    max_len = 0
    char_map = {}
    for right in range(len(s)):
        if s[right] in char_map and char_map[s[right]] >= left:
            left = char_map[s[right]] + 1
        char_map[s[right]] = right
        current_length = right - left + 1
        if current_length > max_len:
            max_len = current_length
    return max_len

def find_maximum_subarray_sums(n: int, array: list) -> list:
    result = [0] * n
    for k in range(1, n + 1):
        current_sum = sum(array[:k])
        max_sum = current_sum
        for i in range(k, n):
            current_sum += array[i] - array[i - k]
            if current_sum > max_sum:
                max_sum = current_sum
        result[k - 1] = max_sum
    return result

def replace_question_marks(s: str) -> str:
    result = []
    for i, char in enumerate(s):
        if char == '?':
            # Determine the previous character
            prev_char = s[i-1] if i > 0 else None
            # Choose a letter different from the previous character
            for letter in 'abcdefghijklmnopqrstuvwxyz':
                if letter != prev_char:
                    result.append(letter)
                    break
        else:
            result.append(char)
    return ''.join(result)

def sum_divisible_by_3_or_5(n: int) -> int:
    def sum_multiples(k: int, limit: int) -> int:
        count = limit // k
        return k * count * (count + 1) // 2

    return sum_multiples(3, n) + sum_multiples(5, n) - sum_multiples(15, n)

