def min_moves_to_palindrome(s: str) -> int:
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i+1][j], dp[i][j-1])

    return dp[0][n-1]

def minimizeSkillDifference(skills: List[int]) -> int:
    total_sum = sum(skills)
    max_sum = total_sum // 2
    dp = [False] * (max_sum + 1)
    dp[0] = True

    for skill in skills:
        for s in range(max_sum, skill - 1, -1):
            if dp[s - skill]:
                dp[s] = True

    for i in range(max_sum, -1, -1):
        if dp[i]:
            return total_sum - 2 * i
    return total_sum

def count_counties_with_castles(a: list, queries: list) -> list:
    a.sort()
    n = len(a)
    results = []
    for x in queries:
        left, right = 0, n
        while left < right:
            mid = (left + right) // 2
            if a[mid] < x:
                left = mid + 1
            else:
                right = mid
        results.append(n - left)
    return results

