def most_frequent_integer(numbers):
    if not numbers:
        return None  # Handle empty list case

    frequency = {}
    for num in numbers:
        frequency[num] = frequency.get(num, 0) + 1

    max_freq = -1
    result = None
    for num, count in frequency.items():
        if count > max_freq:
            max_freq = count
            result = num

    return result

