def count_sentences(s: str, word_dict: set) -> int:
    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1  # Base case: empty string has one way to form it

    for i in range(1, n + 1):
        for j in range(i):
            if s[j:i] in word_dict:
                dp[i] += dp[j]

    return dp[n]

from collections import deque

def find_shortest_path(maze: List[str], n: int, m: int) -> int:
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    start = None
    end = None

    for i in range(n):
        for j in range(m):
            if maze[i][j] == 'S':
                start = (i, j)
            elif maze[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    visited = [[False] * m for _ in range(n)]
    dist = [[float('inf')] * m for _ in range(n)]
    queue = deque()

    queue.append(start)
    visited[start[0]][start[1]] = True
    dist[start[0]][start[1]] = 0

    while queue:
        x, y = queue.popleft()
        if (x, y) == end:
            return dist[x][y]

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and maze[nx][ny] != '#':
                visited[nx][ny] = True
                dist[nx][ny] = dist[x][y] + 1
                queue.append((nx, ny))

    return -1

def findPair(nums: List[int], target: int) -> List[int]:
    seen = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return [seen[complement], i]
        seen[num] = i
    return []

def redistribute_water(containers):
