def max_subarray_length(nums, k):
    n = len(nums)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]

    left = 0
    max_len = 0
    for right in range(n):
        while prefix[right + 1] - prefix[left] > k:
            left += 1
        max_len = max(max_len, right - left + 1)
    return max_len

def levenshtein_distance(source, target):
    m, n = len(source), len(target)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if source[i-1] == target[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
    return dp[m][n]

def damerau_levenshtein_distance(source, target):
    m, n = len(source), len(target)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if source[i-1] == target[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                cost = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
                if i > 1 and j > 1 and source[i-2] == target[j-1] and source[i-1] == target[j-2]:
                    cost = min(cost, dp[i-2][j-2] + 1)
                dp[i][j] = cost
    return dp[m][n]

