def evaluate_expression(expression: str) -> int:
    # Step 1: Tokenize the expression
    tokens = tokenize(expression)

    # Step 2: Convert infix to postfix using shunting-yard algorithm
    postfix = shunting_yard(tokens)

    # Step 3: Evaluate the postfix expression
    result = evaluate_postfix(postfix)

    return result

def tokenize(expression: str) -> list:
    """
    Tokenizes the expression into numbers and operators.
    """
    tokens = []
    i = 0
    while i < len(expression):
        if expression[i].isdigit():
            # Extract the full number
            num = 0
            while i < len(expression) and expression[i].isdigit():
                num = num * 10 + int(expression[i])
                i += 1
            tokens.append(num)
        elif expression[i] in '+-*/':
            tokens.append(expression[i])
            i += 1
        else:
            i += 1
    return tokens

def shunting_yard(tokens: list) -> list:
    """
    Converts infix tokens to postfix tokens using the shunting-yard algorithm.
    """
    output = []
    operators = []
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    left_assoc = {'+': True, '-': True, '*': True, '/': True}

    for token in tokens:
        if isinstance(token, int):
            output.append(token)
        elif token in '+-*/':
            while (operators and operators[-1] in '+-*/' and
                   (precedence[operators[-1]] >= precedence[token] or
                    (precedence[operators[-1]] == precedence[token] and left_assoc[operators[-1]]))):
                output.append(operators.pop())
            operators.append(token)
        else:
            raise ValueError(f"Invalid token: {token}")

    while operators:
        output.append(operators.pop())

    return output

def evaluate_postfix(postfix: list) -> int:
    """
    Evaluates the postfix expression.
    """
    stack = []
    for token in postfix:
        if isinstance(token, int):
            stack.append(token)
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                # Integer division truncates towards zero
                stack.append(int(a / b))
    return stack[0]

