def longest_subarray_with_two_distinct(nums):
    if not nums:
        return 0

    left = 0
    right = 0
    max_length = 0
    count = {}

    while right < len(nums):
        num = nums[right]
        count[num] = count.get(num, 0) + 1

        while len(count) > 2:
            left_num = nums[left]
            count[left_num] -= 1
            if count[left_num] == 0:
                del count[left_num]
            left += 1

        max_length = max(max_length, right - left + 1)
        right += 1

    return max_length

def sumEvenFibonacci(n: int) -> int:
    if n < 0:
        return 0
    a, b = 0, 1
    total = 0
    while a <= n:
        if a % 2 == 0:
            total += a
        a, b = b, a + b
    return total

def minMovesToEqualElements(nums):
    if not nums:
        return 0
    if len(nums) == 1:
        return 0
    if any(x < 0 for x in nums):
        raise ValueError("All elements must be non-negative integers.")
    if any(x != int(x) for x in nums):
        raise ValueError("All elements must be integers.")

    nums.sort()
    n = len(nums)
    median = nums[n // 2]
    return sum(abs(x - median) for x in nums)

def transpose_dict(input_dict):
    """ Transposes the input dictionary of lists """
    # Check if input_dict is empty
    if not input_dict:
        return {}

    # Get the first list to determine the expected length
    first_list = list(input_dict.values())[0]
    expected_length = len(first_list)

    # Check if all lists have the same length
    for values in input_dict.values():
        if len(values) != expected_length:
            raise ValueError("All lists in the input dictionary must have the same length")

    # Create the transposed dictionary
    transposed = {}
    for index in range(expected_length):
        transposed[index] = {}
        for key, values in input_dict.items():
            transposed[index][key] = values[index]

    return transposed

