def simple_prime(limit):
    primes = []
    for num in range(2, limit + 1):
        is_prime = True
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)
    return primes

def max_apples_harvested(N: int, apples: List[int], k: int) -> int:
    if k > N:
        return 0
    current_sum = sum(apples[:k])
    max_sum = current_sum
    for i in range(k, N):
        current_sum += apples[i] - apples[i - k]
        if current_sum > max_sum:
            max_sum = current_sum
    return max_sum

