import heapq

def rearrange_string(s: str) -> str:
    if not s:
        return ""

    # Count frequency of each character
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1

    # Use a max-heap (store as negative values for min-heap simulation)
    heap = []
    for char, count in freq.items():
        heapq.heappush(heap, (-count, char))

    result = []
    last_char = None

    while heap:
        count, char = heapq.heappop(heap)
        count = -count  # Convert back to positive

        # If this character is the same as the last one, skip it
        if char == last_char:
            continue

        # Add the character to the result
        result.append(char)
        last_char = char

        # If there are more occurrences of this character, push it back
        if count > 1:
            heapq.heappush(heap, (-count + 1, char))

    # If the result length is less than the original string, it's impossible
    if len(result) != len(s):
        return ""

    return ''.join(result)

def longest_balanced_parentheses(s: str) -> int:
    stack = []
    max_len = 0
    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            if stack:
                stack.pop()
                max_len = max(max_len, i - stack[-1] if stack else i)
            else:
                stack.append(i)
    return max_len

def is_permutation(a, b):
    if len(a) != len(b):
        return False
    counter = {}
    for num in a:
        counter[num] = counter.get(num, 0) + 1
    for num in b:
        if num not in counter:
            return False
        counter[num] -= 1
        if counter[num] == 0:
            del counter[num]
    return len(counter) == 0

