def count_primes(n: int) -> int:
    """
    Returns the count of prime numbers less than n.
    Uses the Sieve of Eratosthenes for efficiency.
    """
    if n <= 2:
        return 0

    # Sieve array: True means prime, False means composite
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    # Sieve up to sqrt(n)
    limit = int(n ** 0.5) + 1
    for p in range(2, limit):
        if is_prime[p]:
            # Mark multiples of p starting from p*p
            for multiple in range(p * p, n, p):
                is_prime[multiple] = False

    # Count primes
    return sum(is_prime)

