def evaluate_postfix(expression):
    """
    Evaluate a postfix expression using a stack.

    Args:
        expression (str): Postfix expression with space-separated tokens

    Returns:
        float: Result of the evaluation
    """
    stack = []

    # Split the expression into tokens
    tokens = expression.split()

    for token in tokens:
        # If token is a number, push it onto the stack
        if token.replace('.', '', 1).isdigit():
            stack.append(float(token))
        else:
            # If token is an operator, pop two values from stack
            if len(stack) < 2:
                raise ValueError("Insufficient operands for operator")

            # Pop the top two values (second operand first)
            b = stack.pop()
            a = stack.pop()

            # Perform the operation
            if token == '+':
                result = a + b
            elif token == '-':
                result = a - b
            elif token == '*':
                result = a * b
            elif token == '/':
                if b == 0:
                    raise ValueError("Division by zero")
                result = a / b
            elif token == '^':
                result = a ** b
            else:
                raise ValueError(f"Unknown operator: {token}")

            # Push the result back onto the stack
            stack.append(result)

    # The final result should be the only value left in the stack
    if len(stack) != 1:
        raise ValueError("Invalid postfix expression")

    return stack[0]

def main():
    # Example postfix expressions
    examples = [
        "3 4 + 2 *",
        "1 2 + 3 4 * -",
        "2 3 1 + 2 * + 3 +",
        "10 6 9 3 - + 4 * + *",
        "5 1 2 + 4 * + 6 -"
    ]

    print("Postfix Expression Evaluation")
    print("=" * 40)

    for expr in examples:
        try:
            result = evaluate_postfix(expr)
            print(f"{expr} = {result}")
        except ValueError as e:
            print(f"Error evaluating '{expr}': {e}")

