def add_sparse_matrices(mat1, mat2):
    """
    Add two sparse matrices represented as dictionaries of dictionaries.

    Args:
        mat1: First sparse matrix (dict of dicts)
        mat2: Second sparse matrix (dict of dicts)

    Returns:
        New sparse matrix (dict of dicts) with the sum of the two input matrices
    """
    # Determine the maximum row and column indices
    max_row = max(max(mat1.keys(), default=0), max(mat2.keys(), default=0))
    max_col = max(max(mat1[0].keys(), default=0), max(mat2[0].keys(), default=0))

    # Initialize result matrix with dimensions (max_row+1) x (max_col+1)
    result = {}

    # Process each row
    for row in range(max_row + 1):
        # Initialize row if it doesn't exist
        if row not in result:
            result[row] = {}

        # Process each column in the row
        for col in range(max_col + 1):
            # Get values from both matrices (default to 0 if not present)
            val1 = mat1[row].get(col, 0)
            val2 = mat2[row].get(col, 0)

            # Add the values
            total = val1 + val2

            # Only store non-zero values
            if total != 0:
                result[row][col] = total

    return result

