def analyze_word_frequency(text: str) -> dict[str, int]:
    """
    Analyze word frequency from the given text string.

    Args:
    text (str): A string containing the text to analyze.

    Returns:
    dict[str, int]: Dictionary of word frequencies.
    """
    word_freq = {}
    # Convert to lower case and remove punctuation
    text = text.lower()
    text = text.translate(str.maketrans('', '', string.punctuation))

    # Split into words and process
    words = text.split()
    for word in words:
        # Skip empty strings
        if not word:
            continue
        # Skip stop words
        if word in STOP_WORDS:
            continue
        if word in word_freq:
            word_freq[word] += 1
        else:
            word_freq[word] = 1
    return word_freq

