import os
import time

def most_recently_modified(directory):
    """
    Returns the most recently modified file in a directory along with its timestamp.

    Args:
        directory (str): Path to the directory to search

    Returns:
        tuple: (file_path, timestamp) or (None, None) if directory is empty or inaccessible
    """
    most_recent = None
    latest_timestamp = 0

    try:
        # Use os.walk to traverse the directory
        for root, dirs, files in os.walk(directory):
            for filename in files:
                file_path = os.path.join(root, filename)

                try:
                    # Get modification time
                    timestamp = os.path.getmtime(file_path)

                    # Update if this file is more recent
                    if timestamp > latest_timestamp:
                        latest_timestamp = timestamp
                        most_recent = file_path

                except (OSError, PermissionError):
                    # Skip files we can't access
                    continue

    except (OSError, PermissionError):
        # Handle directory access issues
        return None, None

    return most_recent, latest_timestamp

