class Library:
    def __init__(self):
        self.books = {}

    def add_book(self, title, author, year, copies=1):
        """
        Adds a new book to the library or increases the number of copies if the book already exists.
        """
        if title in self.books:
            self.books[title]['copies'] += copies
        else:
            self.books[title] = {
                'title': title,
                'author': author,
                'year': year,
                'copies': copies
            }

    def borrow_book(self, title):
        """
        Borrows a book from the library, if available.
        Raises an error if the book is not available.
        """
        if title not in self.books:
            raise ValueError("Book does not exist in the library.")
        if self.books[title]['copies'] == 0:
            raise ValueError("Book not available or out of stock.")
        self.books[title]['copies'] -= 1

    def return_book(self, title):
        """
        Returns a book to the library.
        Raises an error if the book to return does not exist in the library.
        """
        if title not in self.books:
            raise ValueError("Book does not exist in the library.")
        self.books[title]['copies'] += 1

    def list_books(self):
        """
        Lists all available books in the library.
        """
        return [title for title, book in self.books.items() if book['copies'] > 0]

