def determine_capital(N: int, M: int, A: int, B: int, residents: List[int], roads: List[Tuple[int, int]]) -> int:
    INF = 10**9
    dist = [[INF] * (N + 1) for _ in range(N + 1)]

    for i in range(1, N + 1):
        dist[i][i] = 0

    for u, v in roads:
        dist[u][v] = min(dist[u][v], v - u)
        dist[v][u] = min(dist[v][u], v - u)

    for k in range(1, N + 1):
        for i in range(1, N + 1):
            for j in range(1, N + 1):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    max_dist_A = 0
    max_dist_B = 0
    for i in range(1, N + 1):
        max_dist_A = max(max_dist_A, dist[i][A])
        max_dist_B = max(max_dist_B, dist[i][B])

    if max_dist_A <= max_dist_B:
        return A
