def shortest_path(n: int, grid: List[List[int]], start: Tuple[int, int], destination: Tuple[int, int]) -> int:
    if grid[start[0]][start[1]] == 1 or grid[destination[0]][destination[1]] == 1:
        return -1

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = [[False] * n for _ in range(n)]
    queue = deque()
    queue.append((start[0], start[1], 0))
    visited[start[0]][start[1]] = True

    while queue:
        x, y, dist = queue.popleft()
        if (x, y) == destination:
            return dist
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny] and grid[nx][ny] == 0:
                visited[nx][ny] = True
                queue.append((nx, ny, dist + 1))

    return -1

