def minimize_largest_sum(n: int, k: int, a: List[int]) -> int:
    def can_split(mid):
        count = 1
        current_sum = 0
        for num in a:
            if current_sum + num <= mid:
                current_sum += num
            else:
                count += 1
                current_sum = num
                if count > k:
