def detect_cycle(edges, n):
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    visited = [False] * n
    recursion_stack = [False] * n

    def dfs(node):
        visited[node] = True
        recursion_stack[node] = True

        for neighbor in adj[node]:
            if not visited[neighbor]:
                if dfs(neighbor):
                    return True
            elif recursion_stack[neighbor]:
                return True

        recursion_stack[node] = False
        return False

    for i in range(n):
        if not visited[i]:
            if dfs(i):
                return True
    return False

