    result = []

    def backtrack(start, current, remaining):
        if len(current) == n:
            if remaining == 0:
                result.append(current[:])
            return
        for num in range(start, remaining + 1):
            current.append(num)
            backtrack(num, current, remaining - num)
            current.pop()

