from collections import defaultdict
from typing import List, Tuple

def make_kingdom_tree(n: int, m: int, edges: List[Tuple[int, int]]) -> str:
    graph = defaultdict(list)
    for idx, (u, v) in enumerate(edges):
        graph[u].append((v, idx))
        graph[v].append((u, idx))

    visited = [False] * (n + 1)
    parent = [-1] * (n + 1)
    to_remove = []

    def dfs(node, parent_idx):
        visited[node] = True
        for neighbor, edge_idx in graph[node]:
            if not visited[neighbor]:
                parent[neighbor] = node
                dfs(neighbor, edge_idx)
            elif neighbor != parent[node]:
                to_remove.append(edge_idx)

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, -1)

    if len(to_remove) != m - (n - 1):
        return "NO"

    return "YES\n" + " ".join(map(str, to_remove))

