def find_police_station(n: int, m: int, roads: List[Tuple[int, int]]) -> int:
    # Build adjacency list
    graph = [[] for _ in range(n + 1)]
    for u, v in roads:
        graph[u].append(v)
        graph[v].append(u)

    def bfs(start: int) -> int:
        distances = [-1] * (n + 1)
        queue = deque([start])
        distances[start] = 0
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if distances[neighbor] == -1:
                    distances[neighbor] = distances[node] + 1
                    queue.append(neighbor)
        return max(distances[1:])

    max_distances = [bfs(i) for i in range(1, n + 1)]
    return max_distances.index(min(max_distances))

