class SuffixAutomaton:
    def __init__(self):
        self.next = {}
        self.link = -1
        self.len = 0
        self.last = 0
        self.states = [0]  # State 0 is the initial state

    def extend(self, c):
        cur = len(self.states)
        self.states.append({})
        self.states[cur]['len'] = self.states[self.last]['len'] + 1
        p = self.last
        while p != -1 and c not in self.states[p]:
            self.states[p][c] = cur
            p = self.states[p]['link']
        if p == -1:
            self.states[cur]['link'] = 0
        else:
            q = self.states[p][c]
            if self.states[p]['len'] + 1 == self.states[q]['len']:
                self.states[cur]['link'] = q
            else:
                clone = len(self.states)
                self.states.append({})
                self.states[clone]['len'] = self.states[p]['len'] + 1
                self.states[clone]['next'] = self.states[q]['next'].copy()
                self.states[clone]['link'] = self.states[q]['link']
                while p != -1 and self.states[p][c] == q:
                    self.states[p][c] = clone
                    p = self.states[p]['link']
                self.states[q]['link'] = clone
                self.states[cur]['link'] = clone
        self.last = cur

    def count_unique_substrings(self):
        total = 0
        for state in self.states:
            if state['link'] != -1:
                total += state['len'] - self.states[state['link']]['len']
        return total

