def can_form_triangle(a: int, b: int, c: int) -> bool:
    """
    Determines whether three positive integers can form a valid triangle.
    A valid triangle requires that the sum of any two sides is greater than the third side.
    """
    # Check if all sides are positive integers
    if a <= 0 or b <= 0 or c <= 0:
        return False

    # Check triangle inequality: sum of any two sides > third side
