def _solve_single_case(n: int, m: int, grid: List[List[int]]) -> int:
    if n == 0 or m == 0:
        return 0

    target_set = set()
    for row in grid:
        target_set.update(row)

    for row in grid:
        if set(row) != target_set:
            return -1

    for col in range(m):
        col_set = set()
        for i in range(n):
            col_set.add(grid[i][col])
        if col_set != target_set:
            return -1

    if n == 1 or m == 1:
        return 0

    target_grid = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            target_grid[i][j] = target_set.pop()

    swaps = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] != target_grid[i][j]:
                swaps += 1

    return swaps // 2

