from typing import TypedDict, Callable, Dict, NewType, Protocol

# 1. Define a TypedDict for Task representation
class TaskDict(TypedDict):
    name: str
    priority: int
    execute: Callable[[], bool]

# 2. Define a NewType for TaskID
TaskID = NewType('TaskID', int)

# 3. Define a Protocol for Executable tasks
class Executable(Protocol):
    def execute(self) -> bool:
        ...

# 4. Implement the schedule_tasks function
def schedule_tasks(tasks: Dict[TaskID, TaskDict]) -> Dict[TaskID, bool]:
    """
    Schedule and execute tasks based on priority.

    Args:
        tasks: Dictionary mapping TaskID to TaskDict

    Returns:
        Dictionary mapping TaskID to execution results
    """
    # Sort tasks based on priority (highest first)
    sorted_tasks = sorted(tasks.items(), key=lambda item: item[1]['priority'], reverse=True)

    # Dictionary to store the results
    results: Dict[TaskID, bool] = {}

    # Execute the tasks in sorted order
    for task_id, task in sorted_tasks:
        results[task_id] = task['execute']()

    return results

# 5. Enhanced version with protocol compliance
def schedule_tasks_with_protocol(tasks: Dict[TaskID, TaskDict]) -> Dict[TaskID, bool]:
    """
    Schedule and execute tasks based on priority, ensuring protocol compliance.

    Args:
        tasks: Dictionary mapping TaskID to TaskDict

    Returns:
        Dictionary mapping TaskID to execution results
    """
    # Sort tasks based on priority (highest first)
    sorted_tasks = sorted(tasks.items(), key=lambda item: item[1]['priority'], reverse=True)

    # Dictionary to store the results
    results: Dict[TaskID, bool] = {}

    # Execute the tasks in sorted order
    for task_id, task in sorted_tasks:
        # Ensure the task conforms to the Executable protocol
        if not isinstance(task['execute'], Executable):
            raise TypeError(f"Task {task_id} does not conform to Executable protocol")

        results[task_id] = task['execute']()

    return results

