def countTreeClusters(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]
    clusters = 0

    def dfs(i, j, value):
        if i < 0 or i >= m or j < 0 or j >= n or visited[i][j] or grid[i][j] != value:
            return
        visited[i][j] = True
        dfs(i + 1, j, value)
        dfs(i - 1, j, value)
        dfs(i, j + 1, value)
        dfs(i, j - 1, value)

    for i in range(m):
        for j in range(n):
            if not visited[i][j]:
                dfs(i, j, grid[i][j])
                clusters += 1

    return clusters

