def multiply_sparse_matrices(A, B):
    # Convert matrix A to a list of non-zero elements: (row, col, value)
    A_sparse = []
    for i in range(len(A)):
        for j in range(len(A[0])):
            if A[i][j] != 0:
                A_sparse.append((i, j, A[i][j]))

    # Convert matrix B to a list of non-zero elements: (row, col, value)
    B_sparse = []
    for i in range(len(B)):
        for j in range(len(B[0])):
            if B[i][j] != 0:
                B_sparse.append((i, j, B[i][j]))

    # Initialize result matrix with zeros
    m = len(A)
    n = len(B[0])
    result = [[0] * n for _ in range(m)]

    # Multiply non-zero elements
    for i, j, a_val in A_sparse:
        for k, l, b_val in B_sparse:
            if j == k:
                result[i][l] += a_val * b_val

    return result

