    i = 0
    while i < len(lines):
        n = int(lines[i])
        i += 1
        if i >= len(lines):
            break
        sessions = []
        for _ in range(n):
            if i >= len(lines):
                break
            parts = lines[i].split()
            if len(parts) >= 2:
                start = int(parts[0])
                end = int(parts[1])
                sessions.append((start, end))
            i += 1
        if not sessions:
