    total = len(arr1) + len(arr2)
    if k > total:
        return -1

    merged = []
    i, j = 0, 0
    while i < len(arr1) and j < len(arr2):
        if arr1[i] <= arr2[j]:
            merged.append(arr1[i])
            i += 1
        else:
            merged.append(arr2[j])
            j += 1

    while i < len(arr1):
        merged.append(arr1[i])
        i += 1

    while j < len(arr2):
        merged.append(arr2[j])
        j += 1

    return merged[k-1]

def largest_clique(matrix):
    n = len(matrix)
    max_clique_size = 0

    for mask in range(1 << n):
        clique_size = 0
        for i in range(n):
            if mask & (1 << i):
                clique_size += 1
                for j in range(i + 1, n):
                    if mask & (1 << j) and matrix[i][j] == 0:
                        break
                else:
                    max_clique_size = max(max_clique_size, clique_size)

    return max_clique_size

import heapq

class PriorityQueue:
    def __init__(self, items=None, priorities=None):
        """
        Initialize the priority queue.
        If items and priorities are provided, they must be of equal length.
        """
        self.heap = []
        if items is not None and priorities is not None:
            if len(items) != len(priorities):
                raise ValueError("Items and priorities must have the same length.")
            for item, priority in zip(items, priorities):
                self.push(item, priority)

    def size(self) -> int:
        """
        Return the current size of the queue.
        """
        return len(self.heap)

    def push(self, item: int, priority: int = None) -> None:
        """
        Insert an item with an optional priority.
        If no priority is provided, use the item's value.
        """
        if priority is None:
            priority = item
        heapq.heappush(self.heap, (priority, item))

    def pop(self) -> int:
        """
        Remove and return the item with the lowest priority.
        Raises ValueError if the queue is empty.
        """
        if not self.heap:
            raise ValueError("pop from an empty priority queue")
        priority, item = heapq.heappop(self.heap)
        return item

def min_skill_diff(n: int, skill_levels: List[int]) -> int:
    total_sum = sum(skill_levels)
    target = total_sum // 2
    dp = [False] * (target + 1)
    dp[0] = True

    for skill in skill_levels:
        for s in range(target, skill - 1, -1):
            if dp[s - skill]:
                dp[s] = True

    for i in range(target, -1, -1):
        if dp[i]:
            return total_sum - 2 * i
    return total_sum

