def minimum_travel_time(n: int, m: int, routes: List[Tuple[int, int, int]], queries: List[Tuple[int, int]]) -> List[int]:
    graph = [[] for _ in range(n + 1)]
    for u, v, w in routes:
        graph[u].append((v, w))
        graph[v].append((u, w))

    results = []
    for s, t in queries:
        dist = [float('inf')] * (n + 1)
        dist[s] = 0
        heap = [(0, s)]
        while heap:
            d, u = heapq.heappop(heap)
            if d != dist[u]:
                continue
            if u == t:
                break
            for v, w in graph[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        results.append(dist[t] if dist[t] != float('inf') else -1)
    return results

