from collections import deque, defaultdict

def earliest_time_to_be_virus_free(n: int, m: int, edges: List[Tuple[int, int]], k: int, starting_devices: List[int]) -> int:
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)
    time = [0] * (n + 1)
    q = deque()

    for device in starting_devices:
        visited[device] = True
        time[device] = 0
        q.append(device)

    while q:
        current = q.popleft()
        for neighbor in graph[current]:
            if not visited[neighbor]:
                visited[neighbor] = True
                time[neighbor] = time[current] + 1
                q.append(neighbor)

    if any(not visited[i] for i in range(1, n + 1)):
        return -1
    return max(time[1:])

