def max_knapsack_value(n, W, items):
    if n == 0 or W == 0 or not items:
        return 0

    dp = [[0] * (W + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        weight, value = items[i - 1]
        for w in range(W + 1):
            if weight > w:
                dp[i][w] = dp[i - 1][w]
            else:
                dp[i][w] = max(dp[i - 1][w], dp[i - 1][w - weight] + value)

    return dp[n][W]

def is_tree(n: int, edges: list[tuple[int, int]]) -> bool:
    if n == 0:
        return False
    if len(edges) != n - 1:
        return False

    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    visited = [False] * n
    stack = [0]
    visited[0] = True
    count = 1

    while stack:
        node = stack.pop()
        for neighbor in adj[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                stack.append(neighbor)
                count += 1
            elif visited[neighbor] and neighbor != node:
                return False

    return count == n

