def is_valid_path(maze):
    if not maze or not maze[0]:
        return "no"

    rows = len(maze)
    cols = len(maze[0])

    def dfs(r, c):
        if r < 0 or c < 0 or r >= rows or c >= cols:
            return False
        if maze[r][c] == '#':
            return False
        if r == rows - 1 and c == cols - 1:
            return True

        maze[r][c] = '#'  # Mark as visited

        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dr, dc in directions:
            if dfs(r + dr, c + dc):
                return True

        maze[r][c] = '.'  # Backtrack
        return False

    return "yes" if dfs(0, 0) else "no"

