def determine_winner(S: str) -> str:
    while len(S) > 0:
        found = False
        for i in range(len(S) - 1):
            if S[i] == S[i + 1]:
                start = i
                while start + 1 < len(S) and S[start] == S[start + 1]:
                    start += 1
                end = start
                while end + 1 < len(S) and S[end] == S[end + 1]:
                    end += 1
                if end - start + 1 > 1:
                    S = S[:start] + S[end + 1:]
                    found = True
                    break
        if not found:
            break
    return "Alice" if len(S) == 0 else "Bob"

import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    colors = [int(next(it)) for _ in range(n)]
    costs = [int(next(it)) for _ in range(n)]

    # dp[i][c] = minimum cost to arrange first i cards ending with color c (1,2,3)
    INF = 10**9
    dp = [[INF] * 3 for _ in range(n)]

    # Initialize first card
    for c in range(3):
        if colors[0] == c + 1:
            dp[0][c] = 0
        else:
            dp[0][c] = costs[0]

    # Fill DP table
    for i in range(1, n):
        for c in range(3):
            # If current card already has this color, no cost; else cost to change
            cur_cost = 0 if colors[i] == c + 1 else costs[i]
            # Choose previous color different from current
            for prev in range(3):
                if prev == c:
                    continue
                dp[i][c] = min(dp[i][c], dp[i-1][prev] + cur_cost)

    # Answer is min cost for last card with any color
    ans = min(dp[-1])
    print(ans)

if __name__ == "__main__":
    solve()

